#include "esp_nn.h"
#include "esp_heap_caps.h"

/* NO REPACK BUFFERS. Activations are NHWC end to end -- the layout esp_nn
 * wants -- so the model's own buffers are handed to esp_nn_conv_s8
 * directly. An earlier version of this exporter kept activations in CHW
 * and transposed into scratch on both sides of every conv call; measured
 * on hardware that cost 611 ms of the 1084 ms inference, 57% of the total,
 * to compute nothing. Deleting it took inference to ~466 ms and freed
 * ~600 KB of PSRAM scratch.
 *
 * Note this is specific to models with LARGE activations. The DCT
 * exporter (export_cnn_c_weights.py) still repacks and is right to: its
 * block-grid activations are a few KB, so the transpose is negligible
 * there. A layout mismatch is cheap on small activations and dominant on
 * large ones -- conv0's output here is 307,200 bytes, and the strided
 * writes fall outside cache on every line. */
static int model_esp_nn_scratch_ready = 0;

/* One-time setup: query esp_nn_conv_s8_esp32s3's own internal scratch
 * requirement for every conv layer shape in this model (it varies by shape
 * -- do not hardcode it), take the max, and hand it a single PSRAM buffer
 * reused across every call.
 *
 * The buffer must be 16-BYTE ALIGNED, not merely in PSRAM. This is the real
 * (and only) alignment constraint: with a misaligned scratch pointer the
 * esp32s3 assembly kernel silently corrupts output (mod16==0 bit-exact,
 * mod16==8 most elements wrong). heap_caps_malloc guarantees only 8 bytes,
 * so heap_caps_aligned_alloc is required. An older diagnosis blamed this on
 * kh*in_channels not being a multiple of 16 and added per-layer fallbacks
 * and channel zero-padding; that was wrong and those workarounds were
 * removed after hardware confirmation. Every layer here -- including conv0
 * at in_channels=3 -- goes through esp_nn unconditionally. */
static void model_esp_nn_init(void) {
    if (model_esp_nn_scratch_ready) return;
    int max_scratch = 0;
    {
        data_dims_t in_d = { 32, 24, 3, 0 };
        data_dims_t filt_d = { 3, 3, 3, 0 };
        data_dims_t out_d = { 32, 24, 32, 0 };
        conv_params_t cp = { 0, 0, {1, 1}, {1, 1}, {1, 1}, {0, 127} };
        int sz = esp_nn_get_conv_scratch_size(&in_d, &filt_d, &out_d, &cp);
        if (sz > max_scratch) max_scratch = sz;
    }
    {
        data_dims_t in_d = { 32, 24, 32, 0 };
        data_dims_t filt_d = { 3, 3, 32, 0 };
        data_dims_t out_d = { 16, 12, 32, 0 };
        conv_params_t cp = { 0, 0, {2, 2}, {1, 1}, {1, 1}, {0, 127} };
        int sz = esp_nn_get_conv_scratch_size(&in_d, &filt_d, &out_d, &cp);
        if (sz > max_scratch) max_scratch = sz;
    }
    {
        data_dims_t in_d = { 16, 12, 32, 0 };
        data_dims_t filt_d = { 3, 3, 32, 0 };
        data_dims_t out_d = { 8, 6, 64, 0 };
        conv_params_t cp = { 0, 0, {2, 2}, {1, 1}, {1, 1}, {0, 127} };
        int sz = esp_nn_get_conv_scratch_size(&in_d, &filt_d, &out_d, &cp);
        if (sz > max_scratch) max_scratch = sz;
    }
    {
        data_dims_t in_d = { 8, 6, 64, 0 };
        data_dims_t filt_d = { 3, 3, 64, 0 };
        data_dims_t out_d = { 8, 6, 32, 0 };
        conv_params_t cp = { 0, 0, {1, 1}, {1, 1}, {1, 1}, {0, 127} };
        int sz = esp_nn_get_conv_scratch_size(&in_d, &filt_d, &out_d, &cp);
        if (sz > max_scratch) max_scratch = sz;
    }
    void *scratch = heap_caps_aligned_alloc(16, max_scratch, MALLOC_CAP_SPIRAM);
    esp_nn_set_conv_scratch_buf(scratch);
    model_esp_nn_scratch_ready = 1;
}

static void conv2d_int8(
    const int8_t *input, int in_ch, int H, int W,
    const int8_t *weight, const int32_t *bias, const int32_t *mult, const int32_t *shift,
    int out_ch, int kh, int kw, int stride, int padding, int out_min, int out_max,
    int8_t *output)
{
    model_esp_nn_init();
    int h_out = (H + 2 * padding - kh) / stride + 1;
    int w_out = (W + 2 * padding - kw) / stride + 1;

    data_dims_t input_dims = { W, H, in_ch, 0 };
    data_dims_t filter_dims = { kw, kh, in_ch, 0 };
    data_dims_t output_dims = { w_out, h_out, out_ch, 0 };
    conv_params_t conv_params = {
        .in_offset = 0, .out_offset = 0,
        .stride = { stride, stride }, .padding = { padding, padding }, .dilation = { 1, 1 },
        .activation = { out_min, out_max },
    };
    /* weight is already OHWI -- see format_flat_conv_weight() in
     * export_rgb_cnn_c_weights.py. shift/mult cast away const: esp_nn_conv_s8
     * only ever reads them, quant_data_t's fields just aren't declared const
     * upstream. Not a copy, no correctness risk. */
    quant_data_t quant_data = { .shift = (int32_t *)shift, .mult = (int32_t *)mult };

    /* Model buffers passed straight through -- both are already NHWC. */
    esp_nn_conv_s8(&input_dims, input, &filter_dims, weight, bias,
                   &output_dims, output, &conv_params, &quant_data);
}

#else


/* Portable bit-exact int8 reference -- no ESP-IDF/ESP-NN dependency,
 * compiles and runs anywhere (this is the path the PC verification
 * checks). Same signature as the accelerated version above so
 * model_forward()'s call sites are identical in both builds. int32
 * accumulation (zero-padded), per-output-channel Q31-mantissa requantize,
 * clip.
 *
 * ACTIVATIONS ARE NHWC: input is [H][W][in_ch], output [h_out][w_out][out_ch]
 * -- channel is the fastest-varying axis, matching what esp_nn requires so
 * the accelerated path needs no transpose. Weights stay OIHW here
 * ([out_ch][in_ch][kh][kw]); the ESP-NN build gets an OHWI copy of the same
 * values instead, selected by the #if in the weight tables above. */
static void conv2d_int8(
    const int8_t *input, int in_ch, int H, int W,
    const int8_t *weight, const int32_t *bias, const int32_t *mult, const int32_t *shift,
    int out_ch, int kh, int kw, int stride, int padding, int out_min, int out_max,
    int8_t *output)
{
    int h_out = (H + 2 * padding - kh) / stride + 1;
    int w_out = (W + 2 * padding - kw) / stride + 1;
    for (int oy = 0; oy < h_out; oy++) {
        for (int ox = 0; ox < w_out; ox++) {
            for (int oc = 0; oc < out_ch; oc++) {
                int32_t acc = bias[oc];
                for (int ky = 0; ky < kh; ky++) {
                    int iy = oy * stride + ky - padding;
                    if (iy < 0 || iy >= H) continue;
                    for (int kx = 0; kx < kw; kx++) {
                        int ix = ox * stride + kx - padding;
                        if (ix < 0 || ix >= W) continue;
                        for (int ic = 0; ic < in_ch; ic++) {
                            int8_t in_val = input[(iy * W + ix) * in_ch + ic];
                            int8_t w_val = weight[((oc * in_ch + ic) * kh + ky) * kw + kx];
                            acc += (int32_t)in_val * (int32_t)w_val;
                        }
                    }
                }
                int64_t product = (int64_t)acc * (int64_t)mult[oc];
                int32_t q = model_round_shift(product, 31 - shift[oc]);
                output[(oy * w_out + ox) * out_ch + oc] = (int8_t)model_clip(q, out_min, out_max);
            }
        }
    }
}

#endif /* ESP-NN vs portable conv2d_int8 */

/* Global average pool over an NHWC activation [H][W][C] -> [C] (exact
 * integer average, round to nearest, half away from zero -- matches
 * dct_common/quantization.py:avg_pool_int_exact). Accumulators are held
 * per channel so the input is walked once in memory order rather than C
 * times with a stride, which matters on a PSRAM-resident buffer. */
static void global_avg_pool_int8(const int8_t *input, int C, int H, int W, int8_t *output) {
    int32_t denom = H * W;
    int32_t sums[MODEL_FINAL_CHANNELS];
    for (int c = 0; c < C; c++) sums[c] = 0;
    for (int i = 0; i < H * W; i++)
        for (int c = 0; c < C; c++)
            sums[c] += input[i * C + c];
    for (int c = 0; c < C; c++) {
        int32_t sum = sums[c];
        int32_t abs_sum = sum < 0 ? -sum : sum;
        int32_t rounded = (abs_sum + denom / 2) / denom;
        output[c] = (int8_t)(sum < 0 ? -rounded : rounded);
    }
}

static int model_argmax(const int8_t *values, int n) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (values[i] > values[best]) best = i;
    }
    return best;
}

/* ---- activation buffers ------------------------------------------------
 *
 * ~36 KB of activations for this model -- far past what the ESP32-S3's
 * ~512 KB of internal RAM can hold as stack locals or .bss, so these are
 * allocated once at init and reused. On ESP32 they go to PSRAM; off-target
 * (PC verification builds) plain malloc, so the portable path still
 * compiles and runs anywhere with no ESP-IDF dependency.
 *
 * PSRAM is markedly slower than internal SRAM. That penalty is real and is
 * part of what an RGB-vs-DCT latency comparison is measuring -- it is
 * deliberately not engineered around here.
 */
/* Placement policy: prefer internal SRAM, fall back to PSRAM, keeping
 * MODEL_INTERNAL_RESERVE_BYTES of internal free for WiFi/lwIP and the rest
 * of the firmware. Override that reserve by #define-ing it before including
 * this header. Buffers are requested hottest-first (read traffic per byte,
 * computed at export time from the consuming layer's shape) so the scarce
 * internal budget goes where it buys the most.
 *
 * Placement is RECORDED, not just performed -- model_buffer_report() lets
 * the firmware print where each buffer actually landed. For a latency
 * comparison this matters as much as the timing: an inference time is not
 * interpretable without knowing which activations were in PSRAM. */
#ifndef MODEL_INTERNAL_RESERVE_BYTES
#define MODEL_INTERNAL_RESERVE_BYTES (80 * 1024)
#endif

#if defined(ESP_PLATFORM)
#include "esp_heap_caps.h"
#else
#include <stdlib.h>
#endif

typedef struct {
    const char *name;
    int bytes;
    int internal;   /* 1 = internal SRAM, 0 = PSRAM (or host malloc) */
} model_buffer_info_t;

#define MODEL_NUM_BUFFERS 5

static model_buffer_info_t model_buffer_log[MODEL_NUM_BUFFERS];
static int model_buffer_count = 0;

/* Allocate one buffer, preferring internal SRAM. Records where it landed. */
static void *model_alloc_buffer(const char *name, int nbytes) {
    void *p = 0;
    int internal = 0;
#if defined(ESP_PLATFORM)
    /* 16-byte aligned deliberately. With NHWC activations these buffers are
     * passed straight into esp_nn_conv_s8, i.e. into the esp32s3 assembly
     * kernel, and this library's known failure mode is SILENT output
     * corruption on a misaligned pointer rather than a crash (see
     * model_esp_nn_init below). heap_caps_malloc guarantees only 8 bytes;
     * large blocks often happen to come back 16-aligned, which would make
     * this work by luck and fail on an allocation-pattern change. Cheap to
     * just guarantee it. */
    size_t free_internal = heap_caps_get_free_size(MALLOC_CAP_INTERNAL);
    if ((size_t)nbytes + (size_t)MODEL_INTERNAL_RESERVE_BYTES <= free_internal) {
        p = heap_caps_aligned_alloc(16, nbytes, MALLOC_CAP_INTERNAL);
        internal = (p != 0);
    }
    if (!p) p = heap_caps_aligned_alloc(16, nbytes, MALLOC_CAP_SPIRAM);
#else
    p = malloc(nbytes);
#endif
    if (model_buffer_count < MODEL_NUM_BUFFERS) {
        model_buffer_log[model_buffer_count].name = name;
        model_buffer_log[model_buffer_count].bytes = nbytes;
        model_buffer_log[model_buffer_count].internal = internal;
        model_buffer_count++;
    }
    return p;
}

/* Where each buffer landed. Valid after model_init(); *count is set to the
 * number of entries. */
static const model_buffer_info_t *model_buffer_report(int *count) {
    if (count) *count = model_buffer_count;
    return model_buffer_log;
}

static int8_t *model_q_in = 0;  /* 2304 bytes */
static int8_t *model_conv0_out = 0;  /* 24576 bytes */
static int8_t *model_conv1_out = 0;  /* 6144 bytes */
static int8_t *model_conv2_out = 0;  /* 3072 bytes */
static int8_t *model_conv3_out = 0;  /* 1536 bytes */
static int model_buffers_ready = 0;

/* Allocate every buffer model_forward() needs. Returns 1 on success, 0 if
 * any allocation failed. Safe to call more than once (no-op after the
 * first success). Call this once at startup and CHECK THE RETURN -- if it
 * fails there is not enough memory and model_forward() cannot run. */
static int model_init(void) {
    if (model_buffers_ready) return 1;
    model_q_in = (int8_t *)model_alloc_buffer("q_in", 2304);  /* traffic/byte ~288 */
    model_conv2_out = (int8_t *)model_alloc_buffer("conv2_out", 3072);  /* traffic/byte ~288 */
    model_conv1_out = (int8_t *)model_alloc_buffer("conv1_out", 6144);  /* traffic/byte ~144 */
    model_conv0_out = (int8_t *)model_alloc_buffer("conv0_out", 24576);  /* traffic/byte ~72 */
    model_conv3_out = (int8_t *)model_alloc_buffer("conv3_out", 1536);  /* traffic/byte ~1 */
    if (!model_q_in || !model_conv0_out || !model_conv1_out || !model_conv2_out || !model_conv3_out) return 0;
    model_buffers_ready = 1;
    return 1;
}

/* ---- per-stage profiling hooks -----------------------------------------
 *
 * No-ops unless the firmware defines them BEFORE including this header, so
 * they cost nothing in a normal build. They exist because the whole point
 * of this model on hardware is a per-layer latency breakdown: the
 * hypothesis under test is that conv0 costs far more than its ~11% share of
 * total MACs, and a single aggregate inference time cannot answer that.
 *
 * Example:
 *   static uint32_t t0, stage_us[MODEL_NUM_STAGES];
 *   #define MODEL_PROFILE_BEGIN(s) (t0 = micros())
 *   #define MODEL_PROFILE_END(s)   (stage_us[s] += micros() - t0)
 *   #include "model_weights.h"
 */
enum {
    MODEL_STAGE_QUANTIZE = 0,
    MODEL_STAGE_CONV0 = 1,
    MODEL_STAGE_CONV1 = 2,
    MODEL_STAGE_CONV2 = 3,
    MODEL_STAGE_CONV3 = 4,
    MODEL_STAGE_POOL = 5,
    MODEL_STAGE_DENSE = 6,
    MODEL_NUM_STAGES = 7
};

static const char *const MODEL_STAGE_NAMES[MODEL_NUM_STAGES] = { "quantize", "conv0", "conv1", "conv2", "conv3", "pool", "dense" };

#ifndef MODEL_PROFILE_BEGIN
#define MODEL_PROFILE_BEGIN(stage) ((void)0)
#endif
#ifndef MODEL_PROFILE_END
#define MODEL_PROFILE_END(stage) ((void)0)
#endif

/* Full forward pass: planar uint8 RGB pixels -> int8 logits. Caller owns
 * decode/resize/planar-conversion -- see this header's top comment.
 * Calls model_init() lazily; if allocation fails the logits are zeroed and
 * the call returns without computing anything, so call model_init()
 * explicitly at boot and check its return rather than relying on this.
 *
 * Every stage is bracketed by MODEL_PROFILE_BEGIN/END. The conv primitives
 * and CONV<i>_* weight tables are also individually callable if you want a
 * separately instrumented path rather than these hooks. */
static void model_forward(
    const uint8_t rgb[3][MODEL_RGB_HEIGHT][MODEL_RGB_WIDTH],
    int8_t logits[MODEL_NUM_CLASSES])
{
    if (!model_init()) {
        for (int j = 0; j < MODEL_NUM_CLASSES; j++) logits[j] = 0;
        return;
    }
    /* Caller's rgb[] is planar [3][H][W]; the model wants NHWC, so this
     * loop centers and transposes in one pass. It is the ONLY layout change
     * in the whole forward pass -- everything downstream stays NHWC. */
    MODEL_PROFILE_BEGIN(MODEL_STAGE_QUANTIZE);
    for (int y = 0; y < MODEL_RGB_HEIGHT; y++)
        for (int x = 0; x < MODEL_RGB_WIDTH; x++)
            for (int c = 0; c < 3; c++)
                model_q_in[(y * MODEL_RGB_WIDTH + x) * 3 + c] = (int8_t)((int32_t)rgb[c][y][x] - 128);
    MODEL_PROFILE_END(MODEL_STAGE_QUANTIZE);

    MODEL_PROFILE_BEGIN(MODEL_STAGE_CONV0);
    conv2d_int8(model_q_in, 3, 24, 32,
                CONV0_WEIGHT, CONV0_BIAS, CONV0_MULT, CONV0_SHIFT,
                32, 3, 3, 1, 1, 0, 127, model_conv0_out);
    MODEL_PROFILE_END(MODEL_STAGE_CONV0);

    MODEL_PROFILE_BEGIN(MODEL_STAGE_CONV1);
    conv2d_int8(model_conv0_out, 32, 24, 32,
                CONV1_WEIGHT, CONV1_BIAS, CONV1_MULT, CONV1_SHIFT,
                32, 3, 3, 2, 1, 0, 127, model_conv1_out);
    MODEL_PROFILE_END(MODEL_STAGE_CONV1);

    MODEL_PROFILE_BEGIN(MODEL_STAGE_CONV2);
    conv2d_int8(model_conv1_out, 32, 12, 16,
                CONV2_WEIGHT, CONV2_BIAS, CONV2_MULT, CONV2_SHIFT,
                64, 3, 3, 2, 1, 0, 127, model_conv2_out);
    MODEL_PROFILE_END(MODEL_STAGE_CONV2);

    MODEL_PROFILE_BEGIN(MODEL_STAGE_CONV3);
    conv2d_int8(model_conv2_out, 64, 6, 8,
                CONV3_WEIGHT, CONV3_BIAS, CONV3_MULT, CONV3_SHIFT,
                32, 3, 3, 1, 1, 0, 127, model_conv3_out);
    MODEL_PROFILE_END(MODEL_STAGE_CONV3);

    int8_t pooled[MODEL_FINAL_CHANNELS];
    MODEL_PROFILE_BEGIN(MODEL_STAGE_POOL);
    global_avg_pool_int8(model_conv3_out, MODEL_FINAL_CHANNELS, MODEL_FINAL_H, MODEL_FINAL_W, pooled);
    MODEL_PROFILE_END(MODEL_STAGE_POOL);

    MODEL_PROFILE_BEGIN(MODEL_STAGE_DENSE);
    for (int j = 0; j < MODEL_NUM_CLASSES; j++) {
        int32_t acc = OUTPUT_BIAS[j];
        for (int i = 0; i < MODEL_FINAL_CHANNELS; i++) {
            acc += (int32_t)pooled[i] * (int32_t)OUTPUT_WEIGHT[j][i];
        }
        int64_t product = (int64_t)acc * (int64_t)OUTPUT_MULT[j];
        int32_t q = model_round_shift(product, 31 - OUTPUT_SHIFT[j]);
        logits[j] = (int8_t)model_clip(q, -128, 127); /* raw logits, no activation */
    }
    MODEL_PROFILE_END(MODEL_STAGE_DENSE);
}

#endif /* RGB_CNN_MODEL_WEIGHTS_H */
